class PrefsDelegate(
    private val prefs: SharedPreferences,
    private val key: String,
    private val default: String
) {
    operator fun getValue(thisRef: Any?, property: KProperty<*>): String =
        prefs.getString(key, default) ?: default

    operator fun setValue(thisRef: Any?, property: KProperty<*>, value: String) {
        prefs.edit().putString(key, value).apply()
    }
}

class Settings(prefs: SharedPreferences) {
    var username: String by PrefsDelegate(prefs, "username", "guest")
    // reading/writing username transparently reads/writes SharedPreferences
}

interface Repository { fun getData(): List<String> }

class NetworkRepository : Repository {
    override fun getData(): List<String> = fetchFromNetwork()
}

// delegates all Repository methods to `base` automatically,
// only overriding what actually needs new behavior
class CachingRepository(
    private val base: Repository
) : Repository by base {
    private var cache: List<String>? = null
    override fun getData(): List<String> =
        cache ?: base.getData().also { cache = it }
}
